348	        jdbc.update("DELETE FROM person_patron WHERE sheet_id = ? AND (person_id = ? OR patron_id = ?)", sheetId, id, id);
349	        for (String table : List.of("person_statement", "person_hold", "person_watch", "pool_member")) {
350	            jdbc.update("DELETE FROM " + table + " WHERE sheet_id = ? AND person_id = ?", sheetId, id);
351	        }
352	        jdbc.update("DELETE FROM period_person_total WHERE person_id = ?", id);
353	        for (String table : List.of("person_grade", "person_grade_history", "person_retired_history", "person_alias")) {
354	            jdbc.update("UPDATE " + table + " SET sheet_id = ? WHERE sheet_id = ? AND person_id = ?", to, sheetId, id);
355	        }
356	        jdbc.update("UPDATE person SET sheet_id = ?, statement_count = 0, stated_total = NULL, statement_date = NULL "
357	                + "WHERE sheet_id = ? AND id = ?", to, sheetId, id);
358	    }
359	}
